fun greet(user: User?) {
    val name = user?.name ?: return
    val city = user.address?.city ?: "unknown"
    println("$name from $city")
}

class Box(var item: String?)

fun show(b: Box) {
    b.item?.let { println(it.length) }
    val local = b.item
    if (local != null) println(local.length)
}

class Screen {
    lateinit var adapter: ListAdapter
    val formatter by lazy { DateTimeFormatter.ofPattern("dd/MM") }

    fun ready() = this::adapter.isInitialized
}

